import { useSyncExternalStore } from 'react'

export type Phase = 'title' | 'playing' | 'paused' | 'won' | 'lost'

export type ClueDef = {
  id: string
  label: string
  detail: string
  /** позиция улики на улице */
  pos: [number, number, number]
}

/** Время дела в секундах: не успел — Ноктис тебя не простит. */
export const TOTAL_TIME = 240

/** Улики «Дела о синем мотыльке». Разбросаны по переулку. */
export const CLUES: ClueDef[] = [
  {
    id: 'body',
    label: 'Тело у стены',
    detail: 'Владелец клуба «Синий мотылёк». Удар в затылок, крови почти нет — убивал профессионал.',
    pos: [-3.2, 0.02, -6.5],
  },
  {
    id: 'revolver',
    label: 'Револьвер',
    detail: 'Оружие брошено у бордюра. Барабан на пять, стрелян один патрон. Ствол ещё тёплый.',
    pos: [4.7, 0.02, 1.5],
  },
  {
    id: 'letter',
    label: 'Письмо',
    detail: 'Мокрая записка: «в полночь у трамвая». Почерк ровный, женский. Чернила свежие.',
    pos: [-5.2, 0.02, 8.5],
  },
  {
    id: 'cigarette',
    label: 'Окурок',
    detail: 'Дорогие сигареты, пепел ещё тёплый. Здесь кто-то долго ждал и не нервничал.',
    pos: [5.2, 0.02, -12],
  },
  {
    id: 'badge',
    label: 'Значок',
    detail: 'Полицейский значок 17-го участка. Это не жертва. Это кто-то свой.',
    pos: [1.8, 0.02, 15],
  },
]

/** Куда вернуться после сбора улик. */
export const EXIT_POS: [number, number, number] = [3.6, 0.02, 18]

/** Радиус, с которого улику видно и можно осмотреть. */
export const INTERACT_RADIUS = 2.6

export type Speaker = { name: string; line: string }

export type GameState = {
  phase: Phase
  found: Record<string, boolean>
  foundCount: number
  objective: string
  speaker: Speaker | null
  timeLeft: number
  elapsed: number
  /** ближайшая неподобранная улика в радиусе осмотра */
  nearClue: string | null
  /** все улики собраны — пора к машине */
  canReturn: boolean
}

function initial(): GameState {
  return {
    phase: 'title',
    found: {},
    foundCount: 0,
    objective: 'Осмотри место преступления — найди 5 улик.',
    speaker: {
      name: 'Инспектор Харт',
      line: 'Ноктис, 23:40. Дождь смыл всё, кроме правды. Осмотрись и не тяни — до полуночи я должен знать имя.',
    },
    timeLeft: TOTAL_TIME,
    elapsed: 0,
    nearClue: null,
    canReturn: false,
  }
}

let state: GameState = initial()
const listeners = new Set<() => void>()
let lastSecond = TOTAL_TIME

function emit() {
  for (const l of listeners) l()
}

function set(patch: Partial<GameState>) {
  state = { ...state, ...patch }
  emit()
}

export function subscribe(fn: () => void) {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

export function getState() {
  return state
}

export function useGame() {
  return useSyncExternalStore(subscribe, getState)
}

export function startGame() {
  state = initial()
  state.phase = 'playing'
  lastSecond = TOTAL_TIME
  emit()
}

export function pauseGame() {
  if (state.phase === 'playing') set({ phase: 'paused' })
}

export function resumeGame() {
  if (state.phase === 'paused') set({ phase: 'playing' })
}

export function collectClue(id: string) {
  if (state.phase !== 'playing' || state.found[id]) return
  const clue = CLUES.find((c) => c.id === id)
  if (!clue) return
  const found = { ...state.found, [id]: true }
  const foundCount = Object.keys(found).length
  const all = foundCount >= CLUES.length
  set({
    found,
    foundCount,
    nearClue: null,
    canReturn: all,
    objective: all
      ? 'Все улики собраны. Вернись к полицейской машине и закрой дело.'
      : `Осмотри место преступления — найди улик: ${foundCount} из ${CLUES.length}.`,
    speaker: {
      name: 'Улика',
      line: `${clue.label}. ${clue.detail}`,
    },
  })
}

/** Обновляет ближайшую улику, не дёргая React на каждом кадре. */
export function setNearClue(id: string | null) {
  if (state.nearClue !== id) set({ nearClue: id })
}

/** Тикает таймер; React обновляется только раз в секунду. */
export function tick(dt: number) {
  if (state.phase !== 'playing') return
  const timeLeft = Math.max(0, state.timeLeft - dt)
  const elapsed = state.elapsed + dt
  if (timeLeft <= 0) {
    state = { ...state, timeLeft: 0, elapsed, phase: 'lost' }
    emit()
    return
  }
  const sec = Math.ceil(timeLeft)
  if (sec !== lastSecond) {
    lastSecond = sec
    set({ timeLeft, elapsed })
  } else {
    state = { ...state, timeLeft, elapsed }
  }
}

export function winGame() {
  if (state.phase === 'playing') set({ phase: 'won' })
}

import * as THREE from 'three'

/**
 * Разделяемое состояние управления. Живёт вне React: джойстик и клавиатура
 * пишут сюда, игрок читает в useFrame — без ре-рендеров на каждый кадр.
 */
export const input = {
  /** стик: -1..1, x — вправо, y — вперёд */
  mx: 0,
  my: 0,
  /** куда смотрит камера по горизонтали (рад) */
  cameraYaw: 0,
  /** тащим палец/мышь — вращаем камеру */
  looking: false,
}

export function setStick(x: number, y: number) {
  input.mx = x
  input.my = y
}

const keys = new Set<string>()

export function applyKeys() {
  let x = 0
  let y = 0
  if (keys.has('KeyW') || keys.has('ArrowUp')) y += 1
  if (keys.has('KeyS') || keys.has('ArrowDown')) y -= 1
  if (keys.has('KeyA') || keys.has('ArrowLeft')) x -= 1
  if (keys.has('KeyD') || keys.has('ArrowRight')) x += 1
  // клавиатура приоритетнее, если зажата; иначе стик остаётся как есть
  if (x !== 0 || y !== 0) {
    const len = Math.hypot(x, y)
    setStick(x / len, y / len)
  } else if (!keyboardActive) {
    setStick(0, 0)
  }
}

let keyboardActive = false

/** Привязка клавиатуры (десктоп). Возвращает cleanup. */
export function bindKeyboard() {
  const down = (e: KeyboardEvent) => {
    keyboardActive = true
    keys.add(e.code)
    applyKeys()
  }
  const up = (e: KeyboardEvent) => {
    keys.delete(e.code)
    applyKeys()
    keyboardActive = keys.size > 0
  }
  window.addEventListener('keydown', down)
  window.addEventListener('keyup', up)
  return () => {
    window.removeEventListener('keydown', down)
    window.removeEventListener('keyup', up)
  }
}

const UP = new THREE.Vector3(0, 1, 0)

/** Превращает стик в мировой вектор движения относительно камеры. */
export function stickToWorld(out: THREE.Vector3) {
  const yaw = input.cameraYaw
  const fx = Math.sin(yaw)
  const fz = Math.cos(yaw)
  // right = forward × up
  out.set(fx * input.my + fz * input.mx, 0, fz * input.my - fx * input.mx)
  return out
}

export { UP }

import * as THREE from 'three'

/** Живое состояние игрока — читается камерой и логикой каждый кадр. */
export const playerState = {
  pos: new THREE.Vector3(0, 0.02, 6),
  yaw: Math.PI,
  speed: 0,
  running: false,
}

/** Границы переулка (проезжая часть между бордюрами). */
export const BOUNDS = { minX: -5.8, maxX: 5.8, minZ: -19.5, maxZ: 19.5 }

export const WALK_SPEED = 1.9
export const RUN_SPEED = 4.4

export function resetPlayer() {
  playerState.pos.set(0, 0.02, 6)
  playerState.yaw = Math.PI
  playerState.speed = 0
  playerState.running = false
}

import { useGLTF, useAnimations } from '@react-three/drei'
import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import { clone as cloneSkeleton } from 'three/examples/jsm/utils/SkeletonUtils.js'
import { input, stickToWorld } from './input'
import { playerState, BOUNDS, WALK_SPEED, RUN_SPEED } from './playerState'
import { getState } from './state'

const DETECTIVE = '/models/detective.glb'

/**
 * Управляемый детектив: скелет клонируется через SkeletonUtils, клипы
 * Idle/Walk/Run смешиваются по весам от скорости. Модель смотрит по +Z,
 * поэтому rotation.y = atan2(dir.x, dir.z).
 */
export function Player() {
  const { scene, animations } = useGLTF(DETECTIVE)
  const clone = useMemo(() => cloneSkeleton(scene), [scene])
  const { actions } = useAnimations(animations, clone)

  const group = useRef<THREE.Group>(null)
  const weights = useRef<Record<string, number>>({ Idle: 1, Walk: 0, Run: 0 })
  const target = useRef('Idle')
  const dir = useMemo(() => new THREE.Vector3(), [])

  useEffect(() => {
    for (const n of ['Idle', 'Walk', 'Run']) {
      const a = actions[n]
      if (a) {
        a.reset()
        a.setLoop(THREE.LoopRepeat, Infinity)
        a.setEffectiveWeight(n === 'Idle' ? 1 : 0)
        a.play()
      }
    }
  }, [actions])

  useFrame((_, dt) => {
    const g = group.current
    if (!g) return
    const step = Math.min(dt, 0.05)
    const playing = getState().phase === 'playing'

    const mag = playing ? Math.min(1, Math.hypot(input.mx, input.my)) : 0
    const running = mag > 0.82
    let speed = 0

    if (mag > 0.1) {
      stickToWorld(dir).normalize()
      speed = running ? RUN_SPEED : WALK_SPEED
      playerState.pos.addScaledVector(dir, speed * step)
      playerState.pos.x = THREE.MathUtils.clamp(playerState.pos.x, BOUNDS.minX, BOUNDS.maxX)
      playerState.pos.z = THREE.MathUtils.clamp(playerState.pos.z, BOUNDS.minZ, BOUNDS.maxZ)

      const want = Math.atan2(dir.x, dir.z)
      let diff = want - playerState.yaw
      diff = Math.atan2(Math.sin(diff), Math.cos(diff))
      playerState.yaw += diff * Math.min(1, step * 12)
    }

    playerState.speed = speed
    playerState.running = running

    // веса анимаций: плавно тянем к целевой
    const want = speed === 0 ? 'Idle' : running ? 'Run' : 'Walk'
    target.current = want
    const k = Math.min(1, step * 9)
    for (const n of ['Idle', 'Walk', 'Run']) {
      const a = actions[n]
      if (!a) continue
      const cur = weights.current[n] ?? 0
      weights.current[n] = cur + (Number(n === want) - cur) * k
      a.setEffectiveWeight(weights.current[n])
    }

    g.position.copy(playerState.pos)
    g.rotation.y = playerState.yaw
  })

  return (
    <group ref={group} position={playerState.pos} rotation={[0, playerState.yaw, 0]}>
      <primitive object={clone} />
    </group>
  )
}

